  ($olo$eb75800a-3276-4d1e-bd6b-f2d19fef0f65$olo$, $olo$13bcd88c-01c4-4f95-a218-48108c126a06$olo$, $olo${"root":{"props":{}},"zones":{},"content":[{"type":"MatrizBanner","props":{"id":"matriz-banner","titulo":"Matriz de \n**PERTINENCIA**","imagenAlt":"Matriz de Pertinencia","imagenSrc":"/assets/img/BannerOficial.png"}},{"type":"TextoRico","props":{"id":"matriz-que-es","caja":{"superior":"ninguno","interiorX":"ninguno","interiorY":"ninguno"},"ancho":"ancho","fondo":"blanco","titulo":"¿Qué es?","contenido":"<p>La Matriz de Pertinencia es una herramienta estratégica del SENA, que permite a través de sus 5 variables:</p><ol><li>vinculación laboral.</li><li>tendencia de las ocupaciones.</li><li>demanda social de los programas de oferta titulada.</li><li>sector estratégico de los programas de formación.</li><li>contrato de aprendizaje; comprender que tan bien se ajustan los programas ofrecidos por los centros de formación a la realidad del mercado laboral colombiano.</li></ol>","colorTexto":"#001631"}},{"type":"ImagenDestacada","props":{"id":"matriz-sabias-que","caja":{"ancho":"completo","inferior":"ninguno","superior":"ninguno","interiorX":"ninguno","interiorY":"ninguno","alineacion":"centro"},"ancho":"contenido","fondo":"gris","titulo":"","imagenAlt":"Sabías que... La Matriz ofrece información desde 2011","imagenSrc":"/assets/img/matriz-1.png"}},{"type":"SeccionCarrusel","props":{"id":"matriz-carrusel","fondo":"blanco","titulo":"","autoplay":true,"imagenes":[{"alt":"Matriz de Pertinencia 1","src":"/assets/img/Carrusel1.png"},{"alt":"Matriz de Pertinencia 2","src":"/assets/img/Carrusel2.png"},{"alt":"Matriz de Pertinencia 3","src":"/assets/img/Carrusel3.png"},{"alt":"Matriz de Pertinencia 4","src":"/assets/img/Carrusel4.png"},{"alt":"Matriz de Pertinencia 5","src":"/assets/img/Carrusel5.png"},{"alt":"Matriz de Pertinencia 6","src":"/assets/img/Carrusel6.png"}],"disposicion":"columna","mostrarBotones":true,"imagenesPorPagina":1}},{"type":"TasaVideo","props":{"id":"matriz-video","videoUrl":"https://www.youtube.com/embed/4E7Sci4DAVQ","descargaUrl":"","tituloInicio":"¿Ya sabes como acceder a la matriz de pertinencia en","descargaTexto":"","tituloDestacado":"«CompromISO»?","descargaEtiqueta":"Descargar"}},{"type":"TasaDashboards","props":{"id":"matriz-tableros","tableros":[{"titulo":"Dashboard OLO - Matriz","urlPowerBi":"https://app.powerbi.com/view?r=eyJrIjoiMWIxNWMwYjItNzdhZS00ZGE1LWExMDktYzZhOTgwNjZkNTZmIiwidCI6ImNiYzJjMzgxLTJmMmUtNGQ5My05MWQxLTUwNmM5MzE2YWNlNyIsImMiOjR9&pageName=ReportSection14c82e0795ad03436073","descripcion":"Resultados de vinculación laboral formal (titulada), con una periodicidad semestral. Genera un indicador de vinculación donde se relaciona el número de vinculados laboralmente en el mercado formal y el total de egresados, para un grupo de seguimiento particular."}]}},{"type":"DescargasConPresentacion","props":{"id":"matriz-descargas","titulo":"**Descargas**","enlaces":[{"url":"","etiqueta":"Matriz de pertinencia 2025"},{"url":"","etiqueta":"Matriz de pertinencia 2024"}],"archivoUrl":"/uploads/documents/Presentación1.pptx"}}]}$olo$::jsonb, NULL, 11, $olo$publicado$olo$, NULL, NULL, NULL, '2026-08-19T22:45:14.154Z', '2026-08-19T22:44:32.412Z', NULL, NULL),
  ($olo$57840221-51e7-4177-b242-e7fc43bd83fd$olo$, $olo$cd4c78c5-aeca-47a6-b22f-af1da4cc4d04$olo$, $olo${"root":{"props":{}},"zones":{},"content":[{"type":"EncuestaBanner","props":{"id":"seguimiento-banner","titulo":"SEGUIMIENTO LABORAL","imagenAlt":"Ilustración Seguimiento Laboral","imagenSrc":"/assets/img/banner-seguimiento-laboral.png","antetitulo":"Encuesta de","imagenDerecha":true}},{"type":"TextoRico","props":{"id":"seguimiento-objetivo","caja":{"interiorY":"amplio"},"ancho":"ancho","fondo":"blanco","titulo":"¿Cuál es el **objetivo**?","contenido":"<p>Conocer la transición de nuestros egresados después de su certificación y hacer seguimiento un año después a su proceso de vinculación al mercado laboral.</p><h3>Puntos Específicos:</h3><ul><li>Conocer las actividades en que se desempeñaron los egresados el último año.</li><li>Entender en que actividades productivas se encuentran laborando los egresados después de su certificación.</li><li>Saber como el aprendizaje impartido por el SENA ha contribuido a su vida e intereses en general.</li></ul><h3>¿Qué encontrarás aquí?</h3><ul><li>Una <strong>explicación detallada de la metodología de la encuesta</strong> realizada.</li><li>Los <strong>principales resultados</strong> presentados de forma concisa y visual en una <strong>presentación</strong>.</li><li>El <strong>conjunto de datos brutos</strong> para que pueda realizar su propia exploración y análisis a profundidad.</li></ul>","colorTexto":"#001a38"}},{"type":"ImagenDestacada","props":{"id":"seguimiento-resultados-1","caja":{"inferior":"maximo","alineacion":"derecha"},"ancho":"completo","fondo":"gris","titulo":"","imagenAlt":"Resultados de la encuesta de seguimiento laboral","imagenSrc":"/assets/img/encuesta-seguimiento.png","redondeado":"grande"}},{"type":"ImagenDestacada","props":{"id":"seguimiento-resultados-2","ancho":"completo","fondo":"gris","titulo":"","imagenAlt":"Más resultados de la encuesta de seguimiento laboral","imagenSrc":"/assets/img/encuesta-de-seguimiento-laboral-2.png","redondeado":"grande","ajusteImagen":"contain"}},{"type":"TextoConImagen","props":{"id":"seguimiento-portal","fondo":"blanco","titulo":"Portal de aprendizaje","contenido":"<ul><li><p>Orientación a los nuevos empleados.</p></li><li><p>Rendimiento y desarrollo.</p></li><li><p>Habilidades y aprendizaje.</p></li><li><p>Promociones.</p></li><li><p>Trabajos internos y referencias.</p></li><li><p>Herramientas y métodos.</p></li></ul>","imagenAlt":"","imagenSrc":"","archivoUrl":"/uploads/documents/Presentación1.pptx","ladoImagen":"derecha","pieDeImagen":""}}]}$olo$::jsonb, NULL, 19, $olo$publicado$olo$, NULL, NULL, NULL, '2026-08-19T22:48:30.037Z', '2026-08-19T22:48:00.855Z', NULL, NULL),
  ($olo$93eb9215-0b89-4d2e-bb92-2b1f54f06c82$olo$, $olo$20701c2c-c615-47e5-9323-cc0eab250941$olo$, $olo${"root":{"props":{}},"zones":{},"content":[{"type":"EncuestaBanner","props":{"id":"calidad-banner","titulo":"CALIDAD DE LA FORMACIÓN","imagenAlt":"Ilustración Calidad de la Formación","imagenSrc":"/assets/img/banner-seguimiento-laboral.png","antetitulo":"Encuesta de"}},{"type":"TextoConImagen","props":{"id":"calidad-objetivo","fondo":"blanco","titulo":"¿Cuál es el **objetivo**?","contenido":"<p>El objetivo principal es <strong>evaluar la percepción de los empresarios sobre la contribución de los aprendices en sus organizaciones.</strong></p><h3>Puntos Específicos:</h3><ul><li>Conocer las perspectivas de los empresarios frente al <strong>rol de los aprendices</strong> en sus labores.</li><li>Valorar los conocimientos y habilidades <strong>de los aprendices en un contexto laboral real.</strong></li><li><strong>Ofrecer información</strong> sobre la <strong>pertinencia de la formación</strong> de los aprendices respecto a las demandas del mercado laboral.</li><li>Evaluar la disposición de los empresarios a <strong>contratar aprendices</strong> una vez finalizado su periodo de formación.</li></ul><h3><em>¿Qué encontrarás aquí?</em></h3><ul><li>Una <strong>explicación detallada de la metodología de la encuesta</strong> realizada.</li><li>Los <strong>principales resultados</strong> presentados de forma concisa y visual en una <strong>presentación.</strong></li><li>El <strong>conjunto de datos brutos</strong> para que pueda realizar su propia exploración y análisis a profundidad.</li></ul>","imagenAlt":"Resultado de encuesta - Mapa de disponibilidad a contratar","imagenSrc":"/assets/img/Resultado-de-encuesta.png","ladoImagen":"derecha","pieDeImagen":"Resultado de encuesta calidad de la Formación"}},{"type":"TasaVideo","props":{"id":"calidad-video","videoUrl":"https://www.youtube.com/embed/4E7Sci4DAVQ","descargaUrl":"/uploads/documents/Encuesta Calidad Formación datos.xlsx","tituloInicio":"Aquí te contamos todo sobre la","descargaTexto":"Descarga aquí los datos de la encuesta","tituloDestacado":"encuesta de calidad de la formación","descargaEtiqueta":"Descargar"}},{"type":"DescargasConPresentacion","props":{"id":"calidad-portal","titulo":"Página Web Observatorio Laboral","enlaces":[{"url":"","etiqueta":"Informes"},{"url":"","etiqueta":"Resultados"},{"url":"","etiqueta":"Boletines Tendencia"}],"archivoUrl":"/uploads/documents/Presentación1.pptx"}}]}$olo$::jsonb, NULL, 12, $olo$publicado$olo$, NULL, NULL, NULL, '2026-08-19T22:49:25.817Z', '2026-08-19T22:49:04.459Z', NULL, NULL)
